insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_mukteswar','Mukteswar Temple & Kedar Gouri','Odisha','Khordha','Heritage','Built in the 10th century, Mukteswar marks the transition between early and mid Kalinga architecture. It is world-famous for its unique arched gateway (Torana) influenced by Buddhist architecture, exquisitely carved with women in graceful postures, monkeys, and floral scrolls.','20.2427','85.8398','needs_review','October – March','1',array['temple','heritage','architecture','photography','low cost escape','day trip']::text[],true,'source_linked') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags,coordinate_status=excluded.coordinate_status,suggested_days=excluded.suggested_days,review_status=excluded.review_status;
