insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_rajarani','Rajarani Temple','Odisha','Khordha','Heritage','Built without a presiding deity, Rajarani Temple is revered for its sensual Nayika figures, erotic couples, and intricate floral motifs carved into warm yellow-red sandstone. Host to the prestigious Rajarani Music Festival every winter.','20.252','85.8436','needs_review','October – March','1',array['heritage','architecture','photography','peaceful','low cost escape']::text[],true,'source_linked') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags,coordinate_status=excluded.coordinate_status,suggested_days=excluded.suggested_days,review_status=excluded.review_status;
