insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_dhauli','Dhauli Shanti Stupa & Kalinga War Field','Odisha','Khordha','Heritage','Dhauli Hill marks the battlefield of the legendary Kalinga War (261 BC). Moved by the Daya River turning red with blood, Emperor Ashoka embraced Buddhism and non-violence here. Features Ashoka''s Major Rock Edicts carved in 3rd century BC and a gleaming white Peace Pagoda built jointly by Japan-India Buddhist Association in 1972.','20.1925','85.8394','needs_review','October – March','1',array['buddhism','peace pagoda','history','ashoka','viewpoint','day trip','low cost escape']::text[],true,'source_linked') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags,coordinate_status=excluded.coordinate_status,suggested_days=excluded.suggested_days,review_status=excluded.review_status;
