insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_nandankanan','Nandankanan Zoological Park & Kanjia Lake','Odisha','Khordha','Wildlife','Spanning 437 hectares inside Chandaka forest, Nandankanan (''Garden of Heavens'') became the world''s first zoo to breed white tigers and melanistic tigers. Features open lion and tiger safaris, ropeway over Kanjia Lake, reptile park, and botanical garden.','20.3958','85.8258','needs_review','October – March','1',array['wildlife','zoo','safari','lake','family','day trip','nature']::text[],true,'source_linked') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags,coordinate_status=excluded.coordinate_status,suggested_days=excluded.suggested_days,review_status=excluded.review_status;
