insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_chandaka','Chandaka-Dampara Elephant Sanctuary & Deras Dam','Odisha','Khordha','Wildlife','A crucial elephant habitat located just 20 km from Bhubaneswar city center. Features dense moist deciduous forest, Deras and Jhumka reservoirs, bamboo groves, and watchtowers at Bharatpur and Kumarkhunti for spotting wild elephants, leopards, spotted deer, and barking deer.','20.3556','85.7083','needs_review','October – April','1',array['wildlife','elephants','forest','dam','peaceful','nature','hidden gem','day trip']::text[],true,'source_linked') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags,coordinate_status=excluded.coordinate_status,suggested_days=excluded.suggested_days,review_status=excluded.review_status;
