insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_jagannath','Shree Jagannath Temple Puri','Odisha','Puri','Temple','One of the four sacred Char Dhams of India, built by King Anantavarman Chodaganga Deva in the 12th century. The 214-foot high temple tower holds mysteries like the flag flying opposite to wind, no shadow cast at noon, and the world''s largest traditional kitchen (Rosaghora) preparing Anandbazar Mahaprasad for 100,000 devotees daily.','19.8134','85.8315','needs_review','October – March (Rath Yatra in Jun/Jul)','1',array['temple','spiritual','heritage','char dham','rath yatra','culture']::text[],true,'source_linked') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags,coordinate_status=excluded.coordinate_status,suggested_days=excluded.suggested_days,review_status=excluded.review_status;
