insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_chandrabhaga','Chandrabhaga Beach & Lighthouse','Odisha','Puri','Beach','Located just 3 km from Konark Sun Temple on Marine Drive, Chandrabhaga Beach holds international Blue Flag eco-certification for safety and cleanliness. Known for its historical mythology where river Chandrabhaga met the ocean, it features a functional lighthouse, clean promenade, and quiet golden sands.','19.8667','86.1167','needs_review','October – March','1',array['beach','blue flag','lighthouse','sunset','road trip','peaceful']::text[],true,'source_linked') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags,coordinate_status=excluded.coordinate_status,suggested_days=excluded.suggested_days,review_status=excluded.review_status;
