insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_raghurajpur','Raghurajpur Heritage Craft Village','Odisha','Puri','Heritage','Raghurajpur is Odisha''s premier craft village, nestled amid coconut groves along Bhargavi river. Home to 140 artisan families, every villager is an artist specializing in ancient Pattachitra scroll painting, palm-leaf engraving, wooden toys, and cow-dung papier-mâché masks. Birthplace of legendary Gotipua dance and Guru Kelucharan Mohapatra.','19.8833','85.8333','needs_review','October – March','1',array['pattachitra','craft village','heritage','art','gotipua','culture','low cost escape']::text[],true,'source_linked') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags,coordinate_status=excluded.coordinate_status,suggested_days=excluded.suggested_days,review_status=excluded.review_status;
