insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_pipili','Pipili Applique Craft Town','Odisha','Puri','Heritage','Pipili is world-famous for its traditional Applique (Chandua) handicrafts, a craft origin dating back to the 10th century when tailors prepared canopies and banners for Lord Jagannath''s chariots. The main street is lined with colorful shops displaying vibrant stitched fabric lampshades, garden umbrellas, and wall hangings.','20.1167','85.8333','needs_review','Year-round','1',array['craft','applique','shopping','culture','heritage','road trip']::text[],true,'source_linked') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags,coordinate_status=excluded.coordinate_status,suggested_days=excluded.suggested_days,review_status=excluded.review_status;
