insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_alarnath','Alarnath Temple Brahmagiri','Odisha','Puri','Temple','Alarnath Temple in Brahmagiri holds supreme spiritual importance. During the 15-day ''Anavasara'' period after Snana Yatra when Lord Jagannath is unavailable for darshan, it is believed Lord Jagannath manifests as Alarnath (four-armed Vishnu) here. Associated with Sri Chaitanya Mahaprabhu who meditated on a stone slab that melted under his devotion.','19.8','85.65','needs_review','Year-round (Special in June/July Anavasara)','1',array['temple','spiritual','chaitanya','heritage','day trip']::text[],true,'needs_review') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags,coordinate_status=excluded.coordinate_status,suggested_days=excluded.suggested_days,review_status=excluded.review_status;
insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_sakhigopal','Sakhigopal Temple','Odisha','Puri','Temple','Sakhigopal (''Witness Gopal'') Temple at Satyabadi is tied to the legend of Lord Krishna traveling from Vrindavan to Odisha to testify as witness for a young devotee. Pilgrims visiting Puri Jagannath traditionally complete their pilgrimage with darshan at Sakhigopal. Famous for its Anla Navami festival when Radha''s feet are visible.','19.95','85.8333','needs_review','October – March','1',array['temple','spiritual','krishna','heritage','low cost escape']::text[],true,'source_linked') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags,coordinate_status=excluded.coordinate_status,suggested_days=excluded.suggested_days,review_status=excluded.review_status;
