insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_ansupa','Ansupa Freshwater Lake & Saranda Hill','Odisha','Cuttack','Lake','Ansupa is a picturesque 140-hectare horseshoe freshwater lake formed by the Mahanadi river meander. Flanked by Saranda and Bishnupur hills in Banki sub-division, it welcomes thousands of migratory birds in winter. Features bamboo eco-cottages, boating, tree-top walks, and ancient fort ruins atop Saranda hill.','20.4583','85.6','needs_review','November – February','1',array['lake','freshwater','boating','migratory birds','hill','picnic','day trip']::text[],true,'source_linked') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags,coordinate_status=excluded.coordinate_status,suggested_days=excluded.suggested_days,review_status=excluded.review_status;
